import { Group } from 'three/webgpu';
import gsap from 'gsap';

/**
 * Ornamental divider with machined rule and center jewel.
 * Loads GLB, applies transform, binds hover/click interactions.
 */
export default function createNode(config, ctx) {
  const { scenePosition } = config;
  const { position, rotation, scale } = scenePosition;

  // Load GLB (synchronous – cached)
  const glb = ctx.glbLoader.get(config.meshUrl);
  if (!glb) throw new Error('GLB not loaded: ' + config.meshUrl);

  // Clone to avoid mutating cached scene
  const meshGroup = glb.scene.clone(true);

  // Apply scene placement
  meshGroup.position.set(position.x, position.y, position.z);
  meshGroup.rotation.set(rotation.x, rotation.y, rotation.z);
  meshGroup.scale.set(scale.x, scale.y, scale.z);

  // Track disposable resources for cleanup
  const resources = [];
  meshGroup.traverse(child => {
    if (child.isMesh) {
      resources.push(child.geometry);
      if (Array.isArray(child.material)) {
        child.material.forEach(m => resources.push(m));
      } else {
        resources.push(child.material);
      }
    }
  });

  // Container to return
  const container = new Group();
  container.add(meshGroup);

  // Interaction state
  let hoverTween = null;

  // Handlers
  container.userData.handlers = {
    hover: (active) => {
      if (hoverTween) hoverTween.kill();
      if (active) {
        // Subtle rise-in: increase y by 0.15 scene units
        hoverTween = gsap.to(meshGroup.position, {
          y: position.y + 0.15,
          duration: 0.7,
          ease: 'power3.out',
          overwrite: 'auto',
        });
      } else {
        hoverTween = gsap.to(meshGroup.position, {
          y: position.y,
          duration: 0.5,
          ease: 'power2.out',
          overwrite: 'auto',
        });
      }
    },
    click: () => {
      // Press-down effect (scale 0.97, back.out, yoyo)
      gsap.to(meshGroup.scale, {
        x: scale.x * 0.97,
        y: scale.y * 0.97,
        z: scale.z * 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        yoyo: true,
        repeat: 1,
      });
      // Emit event for navigation / selection
      if (container.userData.emitter) {
        container.userData.emitter.emit('hub-home.select', { source: 'ornamental-divider' });
      }
    },
  };

  // Data binding reference (as per spec)
  container.userData.dataBindings = {
    source: 'trpc.visits.book.slot',
    target: 'confirmPanel',
  };

  // Cleanup
  container.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    resources.forEach(r => {
      if (r && typeof r.dispose === 'function') r.dispose();
    });
    if (container.parent) container.parent.remove(container);
  };

  return container;
}
